:root {
  --color-bg: #f5f5f7;
  --color-card: #ffffff;
  --color-text: #1d1d1f;
  --color-muted: #6e6e73;
  --color-border: #d2d2d7;
  --color-border-focus: #0071e3;
  --color-error: #d93025;
  --color-error-bg: #fef2f2;
  --color-success: #1a7f37;
  --color-success-bg: #f0fdf4;
  --color-accent: #0071e3;
  --color-accent-hover: #0077ed;
  --radius-input: 10px;
  --radius-card: 20px;
  --shadow-card: 0 4px 24px rgba(0, 0, 0, 0.08);
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  -webkit-font-smoothing: antialiased;
}

.page {
  width: 100%;
  max-width: 480px;
}

/* Card */
.card {
  background: var(--color-card);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  padding: 40px 40px 36px;
}

/* Header */
.card-header {
  text-align: center;
  margin-bottom: 32px;
}

.logo-mark {
  font-size: 28px;
  color: var(--color-accent);
  margin-bottom: 12px;
  line-height: 1;
}

.card-header h1 {
  font-size: 24px;
  font-weight: 700;
  letter-spacing: -0.3px;
  color: var(--color-text);
}

.subtitle {
  margin-top: 6px;
  font-size: 14px;
  color: var(--color-muted);
}

/* Form */
form {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

label {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text);
  letter-spacing: 0.1px;
}

.required {
  color: var(--color-error);
  margin-left: 2px;
}

input {
  width: 100%;
  padding: 11px 14px;
  font-size: 15px;
  font-family: inherit;
  color: var(--color-text);
  background: #fafafa;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-input);
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
}

input::placeholder {
  color: #aeaeb2;
}

input:focus {
  background: #fff;
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px rgba(0, 113, 227, 0.15);
}

input.is-invalid {
  border-color: var(--color-error);
  background: var(--color-error-bg);
}

input.is-invalid:focus {
  box-shadow: 0 0 0 3px rgba(217, 48, 37, 0.12);
}

.helper-text {
  font-size: 12px;
  color: var(--color-muted);
}

.error-msg {
  font-size: 12px;
  color: var(--color-error);
  font-weight: 500;
  min-height: 0;
  display: none;
}

.error-msg.visible {
  display: block;
}

/* Submit button */
.btn-submit {
  margin-top: 8px;
  padding: 13px;
  font-size: 15px;
  font-weight: 600;
  font-family: inherit;
  color: #fff;
  background: var(--color-accent);
  border: none;
  border-radius: var(--radius-input);
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
  letter-spacing: 0.1px;
}

.btn-submit:hover {
  background: var(--color-accent-hover);
}

.btn-submit:active {
  transform: scale(0.98);
}

.btn-submit:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

/* Success banner */
.success-banner {
  display: flex;
  align-items: center;
  gap: 14px;
  background: var(--color-success-bg);
  border: 1.5px solid #bbf7d0;
  border-radius: var(--radius-input);
  padding: 16px 18px;
  margin-top: 24px;
}

.success-banner strong {
  font-size: 14px;
  color: var(--color-success);
}

.success-banner p {
  font-size: 13px;
  color: var(--color-muted);
  margin-top: 2px;
}

.success-icon {
  font-size: 20px;
  color: var(--color-success);
  flex-shrink: 0;
  font-weight: 700;
}

.hidden {
  display: none !important;
}

/* Responsive */
@media (max-width: 520px) {
  .card {
    padding: 28px 24px 24px;
  }
}
