  const form = document.getElementById('contact-form');
  const successBanner = document.getElementById('success-banner');

  // Phone: allow optional leading +, digits, spaces, dashes, parens
  const PHONE_RE = /^\+?[\d\s\-().]{7,20}$/;

  function getField(id) {
    return document.getElementById(id);
  }

  function getError(input) {
    return input.closest('.form-field').querySelector('.error-msg');
  }

  function setError(input, message) {
    input.classList.add('is-invalid');
    const err = getError(input);
    err.textContent = message;
    err.classList.add('visible');
  }

  function clearError(input) {
    input.classList.remove('is-invalid');
    const err = getError(input);
    err.textContent = '';
    err.classList.remove('visible');
  }

  function validateName(input) {
    const value = input.value.trim();
    if (!value) {
      setError(input, 'Full name is required.');
      return false;
    }
    clearError(input);
    return true;
  }

  function validateEmail(input) {
    const value = input.value.trim();
    if (!value) {
      setError(input, 'Email address is required.');
      return false;
    }
    if (!input.validity.valid) {
      setError(input, 'Please enter a valid email address.');
      return false;
    }
    clearError(input);
    return true;
  }

  function validatePhone(input) {
    const value = input.value.trim();
    if (value && !PHONE_RE.test(value)) {
      setError(input, 'Please enter a valid phone number (e.g. +1 555 000 0000).');
      return false;
    }
    clearError(input);
    return true;
  }

  // Wire up live validation only after first submit attempt
  function attachLiveValidation() {
    const nameInput = getField('full-name');
    const emailInput = getField('email');
    const phoneInput = getField('phone');

    nameInput.addEventListener('input', () => validateName(nameInput));
    nameInput.addEventListener('blur', () => validateName(nameInput));

    emailInput.addEventListener('input', () => validateEmail(emailInput));
    emailInput.addEventListener('blur', () => validateEmail(emailInput));

    phoneInput.addEventListener('input', () => validatePhone(phoneInput));
    phoneInput.addEventListener('blur', () => validatePhone(phoneInput));
  }

  let liveValidationAttached = false;

  form.addEventListener('submit', function (e) {
    e.preventDefault();

    const nameInput = getField('full-name');
    const emailInput = getField('email');
    const phoneInput = getField('phone');

    const nameOk = validateName(nameInput);
    const emailOk = validateEmail(emailInput);
    const phoneOk = validatePhone(phoneInput);

    if (!liveValidationAttached) {
      attachLiveValidation();
      liveValidationAttached = true;
    }

    if (!nameOk || !emailOk || !phoneOk) {
      // Focus first invalid field
      if (!nameOk) nameInput.focus();
      else if (!emailOk) emailInput.focus();
      else phoneInput.focus();
      return;
    }

    // Simulate submission
    const btn = form.querySelector('.btn-submit');
    btn.disabled = true;
    btn.textContent = 'Sending…';

    setTimeout(() => {
      form.reset();
      btn.disabled = false;
      btn.textContent = 'Send Message';
      successBanner.classList.remove('hidden');
      successBanner.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }, 800);
  });
})();
